pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value, uint256 warp1, uint256 warp2) public {
        // Keep values admissible: non-zero value triggers original require, low value skips it.
        // We let fuzzer pick any value, warp times must be strictly increasing.
        vm.assume(warp2 > warp1);
        vm.assume(warp1 > 0);

        uint256 snapshotBefore = block.timestamp;

        // First call: warp to warp1, send some value (may be zero or 10 ether)
        vm.warp(warp1);
        vm.deal(address(this), value);
        (bool ok1,) = address(c).call{value: value}("");

        if (ok1) {
            // If first call succeeded, pastBlockTime updated to warp1.
            assertEq(c.pastBlockTime(), warp1);
        }

        // Second call: warp to warp2, send zero value.
        vm.warp(warp2);
        vm.deal(address(this), 0);
        (bool ok2,) = address(c).call{value: 0}("");

        if (ok2) {
            // If second call succeeded, pastBlockTime must be warp2 because timestamp > pastBlockTime.
            assertEq(c.pastBlockTime(), warp2);
        } else {
            // If second call reverted, pastBlockTime must remain warp1 (from first call) unchanged.
            assertEq(c.pastBlockTime(), warp1);
        }
    }
}

