    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 block2, uint256 value1, uint256 value2) public {
        // Keep block numbers in a range that allows a transfer on the second call (block2 % 15 == 0)
        // and avoids overflow. value1 and value2 must be exactly 10 ether.
        block2 = bound(block2, 1, 10000);
        vm.assume(block2 % 15 == 0);
        value1 = bound(value1, 10 ether, 10 ether);
        value2 = bound(value2, 10 ether, 10 ether);

