        // Bound warpTime1 and warpTime2 to reasonable timestamps > 0
        warpTime1 = bound(warpTime1, 1, type(uint64).max);
        warpTime2 = bound(warpTime2, 1, type(uint64).max);
        // Ensure first call's timestamp > 0 to pass initial require
