        // Keep blockNum within a wide admissible range; the bug manifests exactly when block.number is a multiple of 15.
        blockNum = bound(blockNum, 1, type(uint128).max);
        vm.roll(blockNum);

        // We need the constructor's address to have enough ether to send 10 ether and then receive back.
        // For correctness we use address(this) as the caller.
        vm.deal(address(this), 10 ether);
        // Warp to a valid future timestamp (must be > 0).
        vm.warp(1);

        // Trigger the fallback with the required 10 ether.
        // low-level call so we can catch revert without a named function.
        (bool success,) = address(c).call{value: 10 ether}("");
        require(success, "call failed");

        // After a successful fallback, if block.number is a multiple of 15 the entire balance should have been transferred out.
        if (blockNum % 15 == 0) {
            assertTrue(address(c).balance == 0);
        } else {
            // Otherwise the balance remains 10 ether.
            assertTrue(address(c).balance == 10 ether);
        }
    }
